function rampartSimulate(createStrategy, seed, maxTicks) {
  'use strict';
  var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var TUR = {
    bolt:   { cost: 50,  dmg: 26,  per: 8,  range: 300, splash: 0,  slow: 0,  pierce: 0, ground: 1, air: 1 },
    cannon: { cost: 90,  dmg: 60,  per: 24, range: 260, splash: 90, slow: 0,  pierce: 0, ground: 1, air: 0 },
    frost:  { cost: 70,  dmg: 10,  per: 12, range: 240, splash: 0,  slow: 30, pierce: 0, ground: 1, air: 1 },
    lance:  { cost: 120, dmg: 180, per: 36, range: 360, splash: 0,  slow: 0,  pierce: 1, ground: 1, air: 0 },
    flak:   { cost: 80,  dmg: 40,  per: 10, range: 320, splash: 70, slow: 0,  pierce: 0, ground: 0, air: 1 }
  };
  var ENM = {
    grunt:    { hp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:   { hp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:     { hp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:    { hp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter: { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:   { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling:{ hp: 0,   speed: 12, bounty: 1, leak: 1, air: 0, first: 99, weight: 0 }
  };
  var ORDER = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  var GP = [[50,250],[650,250],[650,1050],[1250,1050],[1250,350],[1850,350],[1850,1150],[2350,1150]];
  var AP = [[50,650],[2150,650],[2150,1150],[2350,1150]];
  function mk(pts) {
    var segs = [], acc = 0;
    for (var i = 0; i + 1 < pts.length; i++) {
      var a = pts[i], b = pts[i + 1], len = Math.abs(b[0] - a[0]) + Math.abs(b[1] - a[1]);
      segs.push({ x: a[0], y: a[1], dx: Math.sign(b[0] - a[0]), dy: Math.sign(b[1] - a[1]), s: acc, len: len });
      acc += len;
    }
    return { segs: segs, len: acc };
  }
  var ROUTES = [mk(GP), mk(AP)];
  function posAt(route, p) {
    var segs = route.segs, i = 0;
    while (i < segs.length - 1 && p >= segs[i].s + segs[i].len) i++;
    var sg = segs[i], d = p - sg.s;
    if (d > sg.len) d = sg.len;
    return [sg.x + sg.dx * d, sg.y + sg.dy * d];
  }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  var mult = [0, 1000];
  function mOf(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  var waves = [];
  function genWave(w) {
    var avail = [], sum = 0;
    for (var i = 0; i < ORDER.length; i++) if (ENM[ORDER[i]].first <= w) { avail.push(ORDER[i]); sum += ENM[ORDER[i]].weight; }
    var n = 4 + Math.floor(3 * w / 5), out = [];
    for (var k = 0; k < n; k++) {
      var r = rng() % sum, j = 0;
      while (r >= ENM[avail[j]].weight) { r -= ENM[avail[j]].weight; j++; }
      out.push(avail[j]);
    }
    waves[w] = out;
  }
  var log = [];
  var strategy = createStrategy();
  var gold = 250, baseHp = 10, nextId = 1;
  var turrets = new Array(16);
  for (var si = 0; si < 16; si++) turrets[si] = null;
  var enemies = [];
  var queue = []; // spawn entries {tick, wave, idx, type}
  var fallTick = -1, curWave = 0;
  genWave(1);

  function tdmg(t) { var d = TUR[t.type].dmg; for (var k = 1; k < t.tier; k++) d = Math.floor(d * 16 / 10); return d; }
  function trange(t) { return TUR[t.type].range + 30 * (t.tier - 1); }
  function view(e) {
    var p = posAt(ROUTES[e.air], e.progress);
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: p[0], y: p[1], air: e.air, armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: ROUTES[e.air].len - e.progress };
  }
  function addEnemy(type, wave, progress, maxHp) {
    var d = ENM[type];
    var armor = type === 'grunt' ? Math.floor(wave / 4) : (type === 'brute' ? 6 + wave : 0);
    if (maxHp === undefined) maxHp = Math.floor(d.hp * mOf(wave) / 1000);
    var e = { id: nextId++, type: type, wave: wave, hp: maxHp, maxHp: maxHp, speed: d.speed, armor: armor, air: d.air, bounty: d.bounty, leak: d.leak, progress: progress, slow: 0, age: 0, x: 0, y: 0, dead: false };
    var p = posAt(ROUTES[e.air], progress); e.x = p[0]; e.y = p[1];
    enemies.push(e);
    return e;
  }

  for (var tick = 0; tick < maxTicks; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      curWave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      genWave(w + 1);
      var state = {
        tick: tick, wave: w, gold: gold, baseHp: baseHp, slots: [], enemies: [], nextWave: waves[w + 1].slice()
      };
      for (var s = 0; s < 16; s++) {
        var t = turrets[s];
        state.slots.push({ slot: s, x: SLOTS[s][0], y: SLOTS[s][1], turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null });
      }
      for (var q = 0; q < enemies.length; q++) state.enemies.push(view(enemies[q]));
      var acts = strategy.plan(state);
      if (acts && acts.length) {
        var na = Math.min(32, acts.length);
        for (var ai = 0; ai < na; ai++) {
          var a = acts[ai];
          if (!a) continue;
          var slot = a.slot;
          if (typeof slot !== 'number' || slot !== Math.floor(slot) || slot < 0 || slot > 15) continue;
          if (a.op === 'build') {
            var ty = TUR[a.type];
            if (!ty || !Object.prototype.hasOwnProperty.call(TUR, a.type)) continue;
            if (turrets[slot] || gold < ty.cost) continue;
            gold -= ty.cost;
            turrets[slot] = { type: a.type, tier: 1, spent: ty.cost, cd: 0, slot: slot, x: SLOTS[slot][0] * 100 + 50, y: SLOTS[slot][1] * 100 + 50 };
            log.push([tick, 'B', slot, TYPES.indexOf(a.type)]);
          } else if (a.op === 'upgrade') {
            var tt = turrets[slot];
            if (!tt || tt.tier >= 3) continue;
            var cost = TUR[tt.type].cost * (tt.tier === 1 ? 1 : 2);
            if (gold < cost) continue;
            gold -= cost; tt.spent += cost; tt.tier++;
            log.push([tick, 'U', slot, tt.tier]);
          } else if (a.op === 'sell') {
            var st = turrets[slot];
            if (!st) continue;
            gold += Math.floor(st.spent * 70 / 100);
            turrets[slot] = null;
            log.push([tick, 'S', slot, 0]);
          }
        }
      }
      for (var i = 0; i < waves[w].length; i++) queue.push({ tick: tick + 4 * i, wave: w, idx: i, type: waves[w][i] });
    }
    // 2. spawn
    if (queue.length) {
      var rest = [];
      for (var qi = 0; qi < queue.length; qi++) {
        var qe = queue[qi];
        if (qe.tick === tick) addEnemy(qe.type, qe.wave, 0); else rest.push(qe);
      }
      queue = rest;
    }
    // 3. move
    var fell = false;
    for (var mi = 0; mi < enemies.length; mi++) {
      var e = enemies[mi];
      var sp = e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      e.progress += sp;
      var route = ROUTES[e.air];
      if (e.progress >= route.len) {
        baseHp -= e.leak;
        e.dead = true;
        log.push([tick, 'L', e.id, baseHp]);
        if (baseHp <= 0) { fell = true; break; }
      } else {
        var pp = posAt(route, e.progress); e.x = pp[0]; e.y = pp[1];
      }
    }
    if (fell) { fallTick = tick; log.push([tick, 'F', curWave, 0]); break; }
    if (enemies.length) {
      var ne = [];
      for (var k = 0; k < enemies.length; k++) if (!enemies[k].dead) ne.push(enemies[k]);
      enemies = ne;
    }
    // 4. age & heal
    for (var ei = 0; ei < enemies.length; ei++) {
      var m = enemies[ei];
      m.age++;
      if (m.type === 'mender' && m.age % 20 === 0) {
        for (var hj = 0; hj < enemies.length; hj++) {
          var h = enemies[hj];
          var dx = h.x - m.x, dy = h.y - m.y;
          if (dx * dx + dy * dy <= 150 * 150) {
            var nh = h.hp + Math.floor(h.maxHp * 8 / 100);
            h.hp = nh > h.maxHp ? h.maxHp : nh;
          }
        }
      }
    }
    // 5. turrets fire
    for (var ts = 0; ts < 16; ts++) {
      var tu = turrets[ts];
      if (!tu) continue;
      if (tu.cd > 0) tu.cd--;
      if (tu.cd > 0) continue;
      var def = TUR[tu.type], rng2 = trange(tu), r2 = rng2 * rng2;
      var cands = [];
      for (var ci = 0; ci < enemies.length; ci++) {
        var c = enemies[ci];
        if (c.hp <= 0) continue;
        if (c.air ? !def.air : !def.ground) continue;
        var cdx = c.x - tu.x, cdy = c.y - tu.y;
        if (cdx * cdx + cdy * cdy <= r2) cands.push(c);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (strategy.target) {
        var views = cands.map(view);
        var id = strategy.target({ slot: tu.slot, type: tu.type, tier: tu.tier, x: tu.x, y: tu.y, range: rng2 }, views);
        for (var vi = 0; vi < cands.length; vi++) if (cands[vi].id === id) { tgt = cands[vi]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (var bi = 1; bi < cands.length; bi++) {
          var rb = ROUTES[cands[bi].air].len - cands[bi].progress, rt = ROUTES[tgt.air].len - tgt.progress;
          if (rb < rt) tgt = cands[bi];
        }
      }
      var dmg = tdmg(tu);
      var hit = [tgt];
      if (def.splash) {
        hit = [];
        var sr2 = def.splash * def.splash;
        for (var hi = 0; hi < enemies.length; hi++) {
          var he = enemies[hi];
          if (he.hp <= 0) continue;
          if (he.air ? !def.air : !def.ground) continue;
          var hx = he.x - tgt.x, hy = he.y - tgt.y;
          if (hx * hx + hy * hy <= sr2) hit.push(he);
        }
      }
      for (var xi = 0; xi < hit.length; xi++) {
        var he2 = hit[xi];
        var dd = def.pierce ? dmg : Math.max(1, dmg - he2.armor);
        he2.hp -= dd;
        if (def.slow) he2.slow = def.slow;
      }
      tu.cd = def.per;
      // remove dead
      var anyDead = false;
      for (var di = 0; di < enemies.length; di++) if (enemies[di].hp <= 0) { anyDead = true; break; }
      if (anyDead) {
        var snapshot = enemies.slice(), spawned = [];
        for (var di2 = 0; di2 < snapshot.length; di2++) {
          var de = snapshot[di2];
          if (de.hp > 0) continue;
          gold += de.bounty;
          log.push([tick, 'K', de.id, ts]);
          de.dead = true;
          if (de.type === 'splitter') {
            var shp = Math.max(1, Math.floor(de.maxHp / 4));
            for (var sk = 0; sk < 3; sk++) spawned.push([de.wave, de.progress, shp]);
          }
        }
        var kept = [];
        for (var ki = 0; ki < enemies.length; ki++) if (!enemies[ki].dead) kept.push(enemies[ki]);
        enemies = kept;
        for (var spi = 0; spi < spawned.length; spi++) addEnemy('splitling', spawned[spi][0], spawned[spi][1], spawned[spi][2]);
      }
    }
    // 6. slow timers
    for (var zi = 0; zi < enemies.length; zi++) if (enemies[zi].slow > 0) enemies[zi].slow--;
  }
  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  var score = Math.round(((endTick - 20) / 40) * 100) / 100;
  var js = JSON.stringify(log), hsh = 0x811c9dc5;
  for (var hc = 0; hc < js.length; hc++) { hsh ^= js.charCodeAt(hc); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16);
  while (hex.length < 8) hex = '0' + hex;
  return { score: score, fallTick: fallTick, log: log, hash: hex };
}

