  var PRI = { mender: 5, splitter: 3, brute: 2, wisp: 1, grunt: 0, runner: 0, splitling: -1 };
  function score(mode, t, c, all) {
    switch (mode) {
      case 1: return c.hp;                       // highest hp
      case 2: return -c.hp;                      // lowest hp
      case 3: return c.remaining;                // furthest from base
      case 4: return c.armor * 100000 + c.hp;    // most armoured
      case 5: return (PRI[c.type] || 0) * 1000000 - c.remaining; // priority types then closest
      case 6: // cluster
        var n = 0;
        for (var i = 0; i < all.length; i++) { var o = all[i], dx = o.x - c.x, dy = o.y - c.y; if (dx * dx + dy * dy <= 8100) n++; }
        return n * 100000 - c.remaining;
      case 7: return (c.slowed ? 0 : 1) * 1000000 - c.remaining; // unslowed first, then closest
      case 8: return (c.hp > 0 ? 1 : 0) * 1000000 + c.hp * 0 - c.remaining;
      case 9: return c.maxHp - c.remaining * 0.001;
    }
    return -c.remaining;
  }
  return {
    plan: function (s) {
      var acts = [], gold = s.gold, loc = [];
