// usage: jsc search.js -- <procSeed> <iters> <outfile> [startfile]
load('sim.js');
var TPL = read('strat_tpl.js');
var args = arguments;
var PSEED = parseInt(args[0]), ITERS = parseInt(args[1]), OUT = args[2], START = args[3];
function factory(G) {
  var src = TPL.replace(/\/\*GENOME\*\/[\s\S]*?\/\*END\*\//, JSON.stringify(G));
  return new Function(src + '; return createStrategy;')();
}
var TRAIN = []; for (var i = 1; i <= 24; i++) TRAIN.push(1000 + i * 7);
function evalG(G, seeds, mt) {
  var f = factory(G), tot = 0;
  for (var i = 0; i < seeds.length; i++) tot += rampartSimulate(f, seeds[i], mt || 12020).score;
  return tot / seeds.length;
}
var rs = (function (a) { return function () { a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; })(PSEED * 7919 + 13);
function ri(n) { return Math.floor(rs() * n); }
function clone(g) { return JSON.parse(JSON.stringify(g)); }
function mutate(g) {
  g = clone(g);
  var n = 1 + (rs() < 0.4 ? 1 : 0) + (rs() < 0.2 ? 1 : 0);
  for (var k = 0; k < n; k++) {
    var r = rs(), L = g.goals.length;
    if (r < 0.25 && L > 1) { var a = ri(L), b = ri(L); var t = g.goals[a]; g.goals[a] = g.goals[b]; g.goals[b] = t; }
    else if (r < 0.40) { g.goals[ri(L)][1] = ri(5); }
    else if (r < 0.55) { var q = g.goals[ri(L)]; q[2] = 1 + ri(3); }
    else if (r < 0.65) { g.goals[ri(L)][0] = ri(16); }
    else if (r < 0.75 && L > 3) { g.goals.splice(ri(L), 1); }
    else if (r < 0.88) { g.goals.splice(ri(L + 1), 0, [ri(16), ri(5), 1 + ri(3)]); }
    else if (r < 0.95) { var a2 = ri(L), x = g.goals.splice(a2, 1)[0]; g.goals.splice(ri(L), 0, x); }
    else { g.tm[ri(5)] = ri(10); }
  }
  // drop duplicate (slot,type,tier) conflicts? keep as is
  return g;
}
var cur;
if (START) cur = JSON.parse(read(START));
else cur = { goals: [[3, 3, 1], [6, 0, 1], [1, 0, 1], [10, 4, 1], [8, 1, 1], [5, 2, 1], [11, 0, 2], [3, 3, 2], [12, 4, 1], [7, 3, 1]], tm: [0, 0, 0, 0, 0] };
var curS = evalG(cur, TRAIN);
var best = cur, bestS = curS;
var T0 = 0.6;
for (var it = 0; it < ITERS; it++) {
  var cand = mutate(cur), s = evalG(cand, TRAIN);
  var T = T0 * (1 - it / ITERS);
