const DURATION = 100;
window.BENCH_REPORT = {
  selfCheck: { vectorA: false, vectorB: false },
  strategy: { summary: "", seedsTested: 0, meanScoreOnTestedSeeds: null },
  seed42: { score: null, fallTick: null },
  systems: { board: "full", enemiesAndTurrets: "full", combatVisuals: "full", fall: "full", hud: "full", audio: "full" },
  simplifications: [],
  testedInBrowser: false,
  measuredFps: null
};
(function () {
'use strict';
/*REPORT_FILL*/
/* ---------------------------------------------------------------- replay */
const TPS = 20;
const trace = {};
const simRes = rampartSimulate(createStrategy, 42, 2020, trace);
const snaps = trace.snap;
const NS = snaps.length;
const FALL_TICK = simRes.fallTick;
const T_FALL = FALL_TICK >= 0 ? FALL_TICK / TPS : Infinity;
BENCH_REPORT.seed42.score = simRes.score;
BENCH_REPORT.seed42.fallTick = simRes.fallTick;
try {
  const vA = rampartSimulate(function () { return { plan: function (s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: 'build', slot: sl.slot, type: 'bolt' }); g -= 50; } return a; } }; }, 42, 12020);
  BENCH_REPORT.selfCheck.vectorA = vA.score === 25.38 && vA.fallTick === 1035 && vA.log.length === 166 && vA.hash === '82a5353d';
  const vB = rampartSimulate(function () { return { plan: function (s) {
    if (s.wave === 1) return [{ op: 'build', slot: 3, type: 'cannon' }, { op: 'build', slot: 6, type: 'frost' }];
    if (s.wave === 3) return [{ op: 'upgrade', slot: 3 }, { op: 'build', slot: 12, type: 'flak' }];
    if (s.wave === 6) return [{ op: 'build', slot: 8, type: 'lance' }, { op: 'sell', slot: 6 }];
    return []; } }; }, 7, 12020);
  BENCH_REPORT.selfCheck.vectorB = vB.score === 10.93 && vB.fallTick === 457 && vB.log.length === 48 && vB.hash === '2e8858d7';
} catch (e) {}

function mulberry32(a) { return function () {
  a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
const vrng = mulberry32(42);
function vr() { return vrng() / 4294967296; }
function clamp(x, a, b) { return x < a ? a : (x > b ? b : x); }
function smooth(x) { x = clamp(x, 0, 1); return x * x * (3 - 2 * x); }

const TYPE_NAMES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
const ENAMES = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender', 'splitling'];
const ECOL = [0x7f9c68, 0xf2d230, 0x46f0ff, 0x3a3d45, 0x9b4fc9, 0xf4f4f4, 0xb77be0];
const TCOL = [0x5a8fd0, 0xc07a35, 0xe8f6ff, 0xc4163a, 0x1db9a8];
const SLOT_TILES = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
const GROUND_PATH = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
const AIR_PATH = [[0,6],[21,6],[21,11],[23,11]];
const KEEP = { x: 23.35, z: 11.5 };

// precompute per-event data
const leakTimes = [];       // seconds
const traumaImp = [];       // [time, amount]
const killRand = [];
const actRand = [];
for (let j = 0; j < NS; j++) {
  const ev = snaps[j].ev;
  if (!ev) continue;
