  if (shots.length) {
    shots.sort(function (a, b) { return SHOT_RANK[a[5]] - SHOT_RANK[b[5]]; });
    const now = actx.currentTime;
    shotTimes = shotTimes.filter(function (q) { return now - q < 1; });
