  }
}
initAudio();

/* ---------------------------------------------------------------- playback state machine */
const elCount = document.getElementById('countdown'), btnT = document.getElementById('btn-toggle'), btnR = document.getElementById('btn-refire');
const icPause = document.getElementById('icon-pause'), icPlay = document.getElementById('icon-play'), scrub = document.getElementById('scrubber');
const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));
let state = 'COUNTDOWN', simTime = 0, speed = 1.0, cdElapsed = 0, holdElapsed = 0, cdStarted = false, lastTs = null;
function showCount(txt) { elCount.style.display = 'block'; elCount.textContent = txt; }
function hideCount() { elCount.style.display = 'none'; elCount.textContent = ''; }
function setIcons(playing) {
  icPause.style.display = playing ? '' : 'none'; icPlay.style.display = playing ? 'none' : '';
