}
function resetAudioCursor() { audioTick = Math.min(Math.floor(simTime * TPS), NS - 1); }
function enterState(s) {
  state = s;
  if (s === 'PLAYING') { resetAudioCursor(); } else { setAudible(false); }
}
pills.forEach(function (p) {
  p.addEventListener('click', function () {
    speed = parseFloat(p.getAttribute('data-speed'));
