btnT.addEventListener('click', function () {
  resumeAudio();
  if (state === 'PLAYING') { enterState('PAUSED'); setIcons(false); }
  else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') { hideCount(); simTime = 0; scrub.value = '0'; enterState('PAUSED'); setIcons(false); renderFrame(simTime); }
  else if (state === 'PAUSED') { enterState('PLAYING'); setIcons(true); }
  else if (state === 'ENDED') { simTime = 0; scrub.value = '0'; hideCount(); enterState('PLAYING'); setIcons(true); }
});
btnR.addEventListener('click', function () {
  resumeAudio();
  hideCount(); simTime = 0; scrub.value = '0'; holdElapsed = 0;
  setIcons(true); enterState('REFIRE_HOLD'); renderFrame(0);
});
scrub.addEventListener('input', function () {
  hideCount();
