  if (state === 'COUNTDOWN') {
    if (!cdStarted) { cdStarted = true; cdElapsed = 0; } else cdElapsed += dt;
    if (cdElapsed >= 3.0) { hideCount(); enterState('PLAYING'); setIcons(true); }
    else showCount(cdElapsed < 1 ? '3' : (cdElapsed < 2 ? '2' : '1'));
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;
    if (holdElapsed >= 1.0) { enterState('PLAYING'); }
  } else if (state === 'PLAYING') {
    simTime = Math.min(DURATION, simTime + dt * speed);
    scrub.value = simTime.toFixed(3);
    if (simTime >= DURATION) {
      simTime = DURATION; scrub.value = DURATION.toFixed(3);
      renderFrame(simTime);
      enterState('ENDED'); setIcons(false);
      return;
    }
  }
  if (state === 'PLAYING' && actx) {
    setAudible(true);
    audioAdvance(simTime);
    const windOn = simTime >= T_FALL + 1.5;
    windGain.gain.setTargetAtTime(windOn ? 0.12 : 0, actx.currentTime, 0.4);
  }
  renderFrame(simTime);
}
resize();
renderFrame(0);
/*TESTHOOK*/
requestAnimationFrame(frame);
})();

