    case 1: osc('sine', 150 * j, 48, t0, 0.2, 0.2, x); noise('lowpass', 900, 0.7, t0, 0.14, 0.12, x, 200); break;
    case 2: osc('triangle', 2400 * j, 1700 * j, t0, 0.1, 0.04, x); noise('highpass', 5000, 0.7, t0, 0.07, 0.025, x); break;
