load('sim.js');
var TPL = read('strat_tpl.js');
var G = JSON.parse(read(arguments[0]));
var src = TPL.replace(/\/\*GENOME\*\/[\s\S]*?\/\*END\*\//, JSON.stringify(G));
var mk = new Function(src + '; return createStrategy;')();
var names = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender', 'splitling'];
for (var s = 0; s < 8; s++) {
  var seed = 7000 + s * 17, trace = {};
  var last = null;
  var f = function () { var st = mk(); var p = st.plan; st.plan = function (state) { last = state; return p(state); }; return st; };
  var r = rampartSimulate(f, seed, 12020, trace);
  var leaks = {};
  var firstLeak = -1;
  for (var i = 0; i < trace.snap.length; i++) for (var l of trace.snap[i].ev.leaks) { var nm = names[l[1]]; leaks[nm] = (leaks[nm] || 0) + 1; if (firstLeak < 0) firstLeak = i; }
  var comp = {}; last.slots.forEach(function (sl) { if (sl.turret) { var k = sl.turret.type + sl.turret.tier; comp[k] = (comp[k] || 0) + 1; } });
  print('seed ' + seed + ' score ' + r.score + ' firstLeakWave ' + ((firstLeak - 20) / 40 + 1).toFixed(1) + ' leaks ' + JSON.stringify(leaks) + ' gold@last ' + last.gold + ' comp ' + JSON.stringify(comp));
}

